(3893661, 550620, 72579, '<td valign="top">ok</td>', 'ok', '2007-07-11 12:52:01.000000', NULL, 1),
(3893785, 550178, 50100, '<td valign="top">i love the curve of the pencils in your picture! it is very intriguing</td>', 'i love the curve of the pencils in your picture! it is very intriguing', '2007-07-11 13:25:07.000000', NULL, 1),
(3893832, 550439, 80296, '<td valign="top">i like it</td>', 'i like it', '2007-07-11 13:40:20.000000', NULL, 1),
(3894315, 550610, 57229, '<td valign="top">have to give it 8 then . . .</td>', 'have to give it 8 then . . .', '2007-07-11 16:10:05.000000', NULL, 1),
(3894462, 550610, 36382, '<td valign="top">I''m confused.  Why does it say 8?  Aaahh now I get it.  OK very clever, but too clever for me :)</td>', 'I''m confused.  Why does it say 8?  Aaahh now I get it.  OK very clever, but too clever for me :)', '2007-07-11 16:45:55.000000', NULL, 1),
(3894629, 550549, 42495, '<td valign="top">Good colors; neon things appear to be blown out or out of focus.</td>', 'Good colors; neon things appear to be blown out or out of focus.', '2007-07-11 17:21:34.000000', NULL, 1),
(3894672, 550591, 44877, '<td valign="top">Heh - love it.</td>', 'Heh - love it.', '2007-07-11 17:29:16.000000', NULL, 1),
(3894713, 550267, 44877, '<td valign="top">LOL! Funny!</td>', 'LOL! Funny!', '2007-07-11 17:36:57.000000', NULL, 1),
(3894744, 550251, 44877, '<td valign="top">I love the colors on this photo - and the light flares and the different lights  reflected in the water. Interesting shot.</td>', 'I love the colors on this photo - and the light flares and the different lights  reflected in the water. Interesting shot.', '2007-07-11 17:40:25.000000', NULL, 1),
(3894958, 550251, 42495, '<td valign="top">Nice job on the colors - I like the way they cascade down to the water.</td>', 'Nice job on the colors - I like the way they cascade down to the water.', '2007-07-11 18:18:04.000000', NULL, 1),
(3894969, 550326, 42495, '<td valign="top">I saw something similar to this a couple weeks ago.  It was amazing to see them literally play off each other and just go where the music would take them.  Black border is a bit wide for my taste.</td>', 'I saw something similar to this a couple weeks ago.  It was amazing to see them literally play off each other and just go where the music would take them.  Black border is a bit wide for my taste.', '2007-07-11 18:20:20.000000', NULL, 1),
(3894990, 550178, 80904, '<td valign="top">Great shot very well composed.</td>', 'Great shot very well composed.', '2007-07-11 18:23:51.000000', NULL, 1),
(3895383, 550529, 69556, '<td valign="top">I bet this gets about fifty comments.  fotoman... is that u?  lol</td>', 'I bet this gets about fifty comments.  fotoman... is that u?  lol', '2007-07-11 19:22:24.000000', NULL, 1),
(3895416, 550178, 51185, '<td valign="top">this is really awesome</td>', 'this is really awesome', '2007-07-11 19:28:25.000000', NULL, 1),
(3895586, 550095, 55558, '<td valign="top">UFO!</td>', 'UFO!', '2007-07-11 20:17:01.000000', NULL, 1),
(3895661, 550354, 80767, '<td valign="top">Brilliant colors</td>', 'Brilliant colors', '2007-07-11 20:41:14.000000', NULL, 1),
(3895667, 550251, 80767, '<td valign="top">Great shot</td>', 'Great shot', '2007-07-11 20:43:12.000000', NULL, 1),
(3895697, 550594, 75993, '<td valign="top">These wooden figures grate on me like nails on a chalkboard. Creative photo, you just spend too much time with these things.</td>', 'These wooden figures grate on me like nails on a chalkboard. Creative photo, you just spend too much time with these things.', '2007-07-11 20:57:51.000000', NULL, 1),
(3895701, 550529, 75993, '<td valign="top">I don''t know just, yuck! Nice red tones and how it fades to the upper right but overall auh.... yuck!</td>', 'I don''t know just, yuck! Nice red tones and how it fades to the upper right but overall auh.... yuck!', '2007-07-11 20:59:58.000000', NULL, 1),
(3895718, 550534, 37719, '<td valign="top">Pretty small alphabet...not a single letter left in the soup?  :)</td>', 'Pretty small alphabet...not a single letter left in the soup?  :)', '2007-07-11 21:08:18.000000', NULL, 1),
(3895723, 550096, 37719, '<td valign="top">Hmm...I see 8!</td>', 'Hmm...I see 8!', '2007-07-11 21:10:12.000000', NULL, 1),
(3895820, 550533, 42254, '<td valign="top">Striking Photo - Nice work!</td>', 'Striking Photo - Nice work!', '2007-07-11 21:39:25.000000', NULL, 1),
(3895831, 550497, 42254, '<td valign="top">Beautiful contrast &amp; color; a bit too bright on middle leaf at right.</td>', 'Beautiful contrast & color; a bit too bright on middle leaf at right.', '2007-07-11 21:41:13.000000', NULL, 1),
(3895837, 550610, 42254, '<td valign="top">Clever idea and very nice shot--too bad you couldn''t also get the Roman numeral 7.</td>', 'Clever idea and very nice shot--too bad you couldn''t also get the Roman numeral 7.', '2007-07-11 21:42:55.000000', NULL, 1),
(3895855, 550523, 42254, '<td valign="top">Lovely colors, nice shot of model, and adequately blurred background, but some blurred roses. Perhaps a longer lens with with f-stop for adequate depth of field for all in foreground would help.</td>', 'Lovely colors, nice shot of model, and adequately blurred background, but some blurred roses. Perhaps a longer lens with with f-stop for adequate depth of field for all in foreground would help.', '2007-07-11 21:46:36.000000', NULL, 1),
(3895870, 550603, 42254, '<td valign="top">Beautiful shot with the black background!</td>', 'Beautiful shot with the black background!', '2007-07-11 21:50:25.000000', NULL, 1),
(3895881, 550594, 42254, '<td valign="top">I love it! Clever idea and excellent execution with excellent lighting.</td>', 'I love it! Clever idea and excellent execution with excellent lighting.', '2007-07-11 21:52:27.000000', NULL, 1),
(3896077, 550445, 19786, '<td valign="top">Great color.</td>', 'Great color.', '2007-07-11 22:33:32.000000', NULL, 1),
(3896079, 550267, 19786, '<td valign="top">I like your imagination.</td>', 'I like your imagination.', '2007-07-11 22:34:43.000000', NULL, 1),
(3896094, 550215, 19786, '<td valign="top">Fantastic use of color.</td>', 'Fantastic use of color.', '2007-07-11 22:39:00.000000', NULL, 1),
(3896110, 550529, 66494, '<td valign="top">LOL</td>', 'LOL', '2007-07-11 22:45:05.000000', NULL, 1),
(3896114, 550534, 19786, '<td valign="top">Nice layout and use of color.</td>', 'Nice layout and use of color.', '2007-07-11 22:45:36.000000', NULL, 1),
(3896115, 550389, 66494, '<td valign="top">Beautiful image, my top choice. 10.</td>', 'Beautiful image, my top choice. 10.', '2007-07-11 22:45:46.000000', NULL, 1),
(3896118, 550484, 66494, '<td valign="top">Very clever and very well done. 9</td>', 'Very clever and very well done. 9', '2007-07-11 22:46:03.000000', NULL, 1),
(3896121, 550377, 19786, '<td valign="top">Great shot, how did you get them still long enough to shoot?</td>', 'Great shot, how did you get them still long enough to shoot?', '2007-07-11 22:47:09.000000', NULL, 1),
(3896144, 550267, 61651, '<td valign="top">I''m thinking Shirley Jackson''s The Lottery for some reason!  This is has a slightly surreal air of menace to it - I mean this all as a compliment, I think it''s a very fun shot!</td>', 'I''m thinking Shirley Jackson''s The Lottery for some reason!  This is has a slightly surreal air of menace to it - I mean this all as a compliment, I think it''s a very fun shot!', '2007-07-11 22:52:32.000000', NULL, 1),
(3896197, 550328, 69246, '<td valign="top">DNMC</td>', 'DNMC', '2007-07-11 23:03:51.000000', NULL, 1),
(3896201, 550587, 69246, '<td valign="top">DNMC - Seven OF the main subject.</td>', 'DNMC - Seven OF the main subject.', '2007-07-11 23:05:17.000000', NULL, 1),
(3896213, 550095, 69246, '<td valign="top">Just doesn''t stand out enough.</td>', 'Just doesn''t stand out enough.', '2007-07-11 23:07:56.000000', NULL, 1),
(3896215, 550529, 60910, '<td valign="top">wow that is a lot of vibrators, perhaps you should get out more?</td>', 'wow that is a lot of vibrators, perhaps you should get out more?', '2007-07-11 23:08:19.000000', NULL, 1),
(3896347, 550444, 6179, '<td valign="top">Nice. I give it a ''7''.  ;-)</td>', 'Nice. I give it a ''7''.  ;-)', '2007-07-11 23:38:41.000000', NULL, 1),
(3896840, 550417, 28801, '<td valign="top">I like the dual interpretation: 7 rafters (reverse)7-shaped roof.</td>', 'I like the dual interpretation: 7 rafters (reverse)7-shaped roof.', '2007-07-12 04:19:10.000000', NULL, 1),
(3896944, 550579, 48954, '<td valign="top">where''s the focus? if your main subject, and only subject in this case, isn''t in focus, what the point? If you are using a digital camera, why not take the shot again, but in focus?</td>', 'where''s the focus? if your main subject, and only subject in this case, isn''t in focus, what the point? If you are using a digital camera, why not take the shot again, but in focus?', '2007-07-12 06:55:51.000000', NULL, 1),
(3896946, 550553, 48954, '<td valign="top">it''s not very abstract ;) The cropping on the left is awkward i find and throws off the balance.</td>', 'it''s not very abstract ;) The cropping on the left is awkward i find and throws off the balance.', '2007-07-12 06:56:53.000000', NULL, 1),
(3896947, 550605, 48954, '<td valign="top">why did you crop off the bottom on the window frame? it''s the main subject here and should have been all in with some red at the bottom to spare</td>', 'why did you crop off the bottom on the window frame? it''s the main subject here and should have been all in with some red at the bottom to spare', '2007-07-12 06:58:01.000000', NULL, 1),
