(3898910, 550499, 42254, '<td valign="top">Are there 7 buildings? --can''t be sure. Nice pastoral scene, though not striking.</td>', 'Are there 7 buildings? --can''t be sure. Nice pastoral scene, though not striking.', '2007-07-12 21:03:04.000000', NULL, 1),
(3898914, 550499, 65468, '<td valign="top">Less sky &amp; more contrast would have made this a higher rated image IMHO</td>', 'Less sky & more contrast would have made this a higher rated image IMHO', '2007-07-12 21:05:40.000000', NULL, 1),
(3898917, 550475, 42254, '<td valign="top">Great color!  A very appealing shot, though a bit better without the reflections &amp; shadows.</td>', 'Great color!  A very appealing shot, though a bit better without the reflections & shadows.', '2007-07-12 21:06:21.000000', NULL, 1),
(3898921, 550408, 42254, '<td valign="top">Would benefit from better contrast with backround; purple too close to the blue.  Not sure I see the point of the arrangement.</td>', 'Would benefit from better contrast with backround; purple too close to the blue.  Not sure I see the point of the arrangement.', '2007-07-12 21:07:45.000000', NULL, 1),
(3898922, 550399, 42254, '<td valign="top">Too bright to show off jewelry well; harsh lighting?</td>', 'Too bright to show off jewelry well; harsh lighting?', '2007-07-12 21:08:35.000000', NULL, 1),
(3898925, 550601, 42254, '<td valign="top">Clever idea, but overexposed.  I do like the shooting angle as opposed to head on horizontal/vertical.</td>', 'Clever idea, but overexposed.  I do like the shooting angle as opposed to head on horizontal/vertical.', '2007-07-12 21:10:19.000000', NULL, 1),
(3898926, 550579, 42254, '<td valign="top">Beautiful color and contrast, but flowers seem blurred without reason.</td>', 'Beautiful color and contrast, but flowers seem blurred without reason.', '2007-07-12 21:11:02.000000', NULL, 1),
(3898933, 550564, 42254, '<td valign="top">Confusing &amp; dark.</td>', 'Confusing & dark.', '2007-07-12 21:13:30.000000', NULL, 1),
(3898936, 550473, 42254, '<td valign="top">Nice abstract art photo using pages of a book, I would guess from the title.  Nice use of pastel colors.</td>', 'Nice abstract art photo using pages of a book, I would guess from the title.  Nice use of pastel colors.', '2007-07-12 21:15:05.000000', NULL, 1),
(3898942, 550453, 42254, '<td valign="top">Unsharp &amp; random arrangement that doesn''t seem to have any purpose. They are a nice color.</td>', 'Unsharp & random arrangement that doesn''t seem to have any purpose. They are a nice color.', '2007-07-12 21:17:52.000000', NULL, 1),
(3898945, 550591, 42254, '<td valign="top">Perhaps more contrast with background would help, although a death metaphor might be implied by the dark flower centers. But not from the title.</td>', 'Perhaps more contrast with background would help, although a death metaphor might be implied by the dark flower centers. But not from the title.', '2007-07-12 21:19:42.000000', NULL, 1),
(3898946, 550397, 42254, '<td valign="top">Beautiful color, composition, and lighting!</td>', 'Beautiful color, composition, and lighting!', '2007-07-12 21:21:24.000000', NULL, 1),
(3898964, 550372, 67697, '<td valign="top">Cornhole?  love the alternating colors.</td>', 'Cornhole?  love the alternating colors.', '2007-07-12 21:31:56.000000', NULL, 1),
