(3898975, 550478, 67697, '<td valign="top">lol.  Love the faces on the calendar. What a fun pic!</td>', 'lol.  Love the faces on the calendar. What a fun pic!', '2007-07-12 21:35:18.000000', NULL, 1),
(3898978, 550605, 67697, '<td valign="top">Interesting find.  I like the shadows on the wall and window.</td>', 'Interesting find.  I like the shadows on the wall and window.', '2007-07-12 21:35:51.000000', NULL, 1),
